import { gs, GlideRecord } from '@servicenow/glide';
import { forbidden, notFound, requireSysId } from './http';
export const T = {
    profile: 'x_312586_gintake_profile',
    criterion: 'x_312586_gintake_criterion',
    profCrit: 'x_312586_gintake_prof_crit',
    session: 'x_312586_gintake_session',
    response: 'x_312586_gintake_response',
};
export const ROLE = {
    admin: 'x_312586_gintake.admin',
    reviewer: 'x_312586_gintake.reviewer',
};
/*
 * The API reads and writes with GlideRecord (not GlideRecordSecure) because
 * it must set system-managed fields that are admin-write at the ACL level.
 * Every handler therefore enforces ownership explicitly through these helpers.
 */
export const me = () => gs.getUserID();
export const isAdmin = () => gs.hasRole(ROLE.admin);
export const isReviewer = () => gs.hasRole(ROLE.reviewer);
/** Loads a session and asserts the caller may read it (owner, reviewer, or admin). */
export function sessionForRead(id) {
    const s = loadSession(id);
    if (s.getValue('requester') !== me() && !isReviewer() && !isAdmin())
        throw notFound('Session');
    return s;
}
/** Loads a session and asserts the caller owns it (or is admin). */
export function sessionForWrite(id) {
    const s = loadSession(id);
    if (s.getValue('requester') !== me() && !isAdmin()) {
        // Reviewers can see the session but don't get to say whether it exists for writes either.
        throw isReviewer() ? forbidden('Only the requester can change this session') : notFound('Session');
    }
    return s;
}
function loadSession(id) {
    requireSysId(id, 'Session id');
    const s = new GlideRecord(T.session);
    if (!s.get(id))
        throw notFound('Session');
    return s;
}
